uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// User Parameters
uniform float u_speed;
uniform float u_scale;
uniform float u_sparkle;
uniform float u_glow;
uniform float u_hue;   
uniform float u_hue2;  

// AI Aesthetic Parameters
uniform float u_neuro_complexity; 
uniform float u_chromatic_aberration; 
uniform float u_bass; 
uniform float u_glitch_intensity; 

// "Mad" Parameters
uniform float u_rage_intensity; 
uniform float u_distortion_warp; 

// New control for the auto-oscillation speed
uniform float u_neuro_cycle_speed;

out vec4 fragColor;

// --- Helper Functions ---
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float hash(float n) {
    return fract(sin(n) * 43758.5453123);
}

// Buttery smooth organic noise
float fbm(vec2 p, float rage, float bassParam) {
    float v = 0.0;
    float a = 0.5;
    vec2 shift = vec2(100.0);
    for (int i = 0; i < 4; ++i) {
        v += a * (sin(p.x) + cos(p.y));
        // Rotate and scale, infused with bass reactivity
        p = rot(0.5 + rage * 0.2) * p * (1.8 + bassParam * 0.5) + shift;
        a *= 0.5;
    }
    return v;
}

// HSB to RGB Conversion
vec3 hsb2rgb(vec3 c) {
    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    rgb = rgb * rgb * (3.0 - 2.0 * rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

void main() {
    // --- ZERO-STATE SAFETY LOGIC ---
    float speed = (u_speed <= 0.001) ? 0.05 : u_speed * 0.1; 
    float scale = (u_scale <= 0.001) ? 3.0 : u_scale;
    float sparkleInt = (u_sparkle <= 0.001) ? 0.6 : u_sparkle;
    float glowInt = (u_glow <= 0.001) ? 1.5 : u_glow;
    float hue1 = (u_hue <= 0.001 && u_hue2 <= 0.001) ? 0.55 : u_hue;
    float hue2 = (u_hue <= 0.001 && u_hue2 <= 0.001) ? 0.85 : u_hue2;

    // --- NEURO COMPLEXITY AUTO-ADJUSTMENT ---
    float cycleTime = iTime * (0.104719 * u_neuro_cycle_speed); 
    float neuroAuto = (sin(cycleTime) * 0.5 + 0.5) * 1.2;
    float neuro = u_neuro_complexity + neuroAuto;

    float caParam = u_chromatic_aberration;
    float bass = u_bass;
    float glitch = u_glitch_intensity;
    float rage = u_rage_intensity;
    float warp = u_distortion_warp;

    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;
    float time = iTime * speed;

    // Shake & Glitch 
    float shake = hash(floor(iTime * 15.0)) * rage * 0.02;
    uv += vec2(shake, -shake);

    if (glitch > 0.0) {
        float sliceY = floor(uv.y * 20.0);
        if (fract(sin(sliceY + iTime) * 123.4) > 0.95 - glitch * 0.1) {
            uv.x += (fract(sin(iTime + sliceY) * 456.7) - 0.5) * 0.1 * glitch;
        }
    }

    // Lush AI Liquid Warp (Base distortion)
    float fluid = fbm(uv * (2.0 + warp) - time * 0.2, rage, bass) * (neuro + rage);
    uv += fluid * (0.05 + warp * 0.05);

    // Deep lush background - removed time dependency from base hue to prevent snapping
    vec3 bgCol = hsb2rgb(vec3(mix(hue1, hue2, 0.5), mix(0.8, 1.0, rage), 0.03 + fluid * 0.02));
    vec3 finalColor = bgCol;

    // --- CONTINUOUS DEPTH LOOP ---
    const int LAYERS = 12;

    for (int i = 0; i < LAYERS; i++) {
        float fi = float(i);

        // Depth continuously drops from 1.0 (distant) to 0.0 (camera)
        float z = fract(fi / 12.0 - time * 0.1);

        // Smooth entry and exit fading
        float fade = smoothstep(0.0, 0.2, z) * smoothstep(1.0, 0.7, z);

        // Scale the coordinate space
        float layerScale = mix(20.0, 1.0, 1.0 - z) / scale;
        vec2 p = uv * layerScale;

        // Twist the tunnel
        p *= rot(z * warp * 2.0 + time * 0.05 + fi);

        // Organic drift
        p += vec2(sin(p.y * 0.5 + time * 0.5), cos(p.x * 0.5 - time * 0.5)) * 0.5;

        // --- CONTINUOUS DOMAIN CIRCLES ---
        float ca = (caParam + rage * 0.5) * 0.2 * (1.0 - z);

        float dR = length(sin(p - ca));
        float dG = length(sin(p));
        float dB = length(sin(p + ca));

        // Radius pulses with bass
        float radius = 0.4 * (1.0 + bass * 0.8);

        // Core shapes
        float coreR = smoothstep(radius + 0.1, radius - 0.1, dR);
        float coreG = smoothstep(radius + 0.1, radius - 0.1, dG);
        float coreB = smoothstep(radius + 0.1, radius - 0.1, dB);

        // Exponential Lush Glows
        float glowSharpness = 8.0 / (glowInt + 0.001); 
        float glowR = exp(-abs(dR - radius) * glowSharpness) * glowInt * (1.0 + rage);
        float glowG = exp(-abs(dG - radius) * glowSharpness) * glowInt;
        float glowB = exp(-abs(dB - radius) * glowSharpness) * glowInt;

        // Palette mapping: Removed fract(time) based hue shifts that cause snaps.
        // Now it uses a static blend between hue1 and hue2 based on layer index and distance z.
        float layerHue = mix(hue1, hue2, z); 
        layerHue = mix(layerHue, hash(fi), rage * 0.2); // Reduced random hue influence for stability
        vec3 col = hsb2rgb(vec3(layerHue, mix(0.7, 1.0, rage + bass), 1.0));

        // Compile the layer
        vec3 layerColor = vec3(0.0);
        layerColor.r += col.r * (glowR + coreR * 0.3);
        layerColor.g += col.g * (glowG + coreG * 0.3);
        layerColor.b += col.b * (glowB + coreB * 0.3);

        // --- CONTINUOUS SPARKLES ---
        float sparkVal = max(0.0, sin(p.x * 8.0 + time * 0.5) * sin(p.y * 8.0 - time * 0.7));
        sparkVal = pow(sparkVal, 15.0) * sparkleInt * 8.0;

        vec3 sparkleCol = mix(vec3(1.0), col, 0.3);
        layerColor += sparkleCol * sparkVal * glowG; 

        finalColor += layerColor * fade * (1.5 - z);
    }

    // Vignette
    finalColor *= (1.2 + rage * 0.5) - length(uv0) * (0.8 + rage * 0.6);

    // AI Tone Mapping
    finalColor = pow(finalColor, vec3(0.9 - rage * 0.3)); 
    finalColor = smoothstep(-0.05, 1.15 + rage * 0.5, finalColor);

    fragColor = vec4(finalColor, 1.0);
}
